insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('weekly-energy-map-page', 'Weekly Energy Map Page', 'worksheet'::resource_kind, 'Clients chart high and low energy hours across a week to plan around them.', 'Use it to help a client place demanding tasks where their energy tends to be.', array['Adults']::text[], 'One week', 'Ask the client to rate energy a few times a day and bring the page back. Look together for patterns in time of day, sleep, food timing and company. Keep it descriptive; the point is planning, not judging a slow day.', '[{"id": "f0", "type": "textarea", "label": "Morning energy (1 to 10) each day and what came before it:"}, {"id": "f1", "type": "textarea", "label": "Afternoon and evening energy and what came before it:"}, {"id": "f2", "type": "textarea", "label": "The times I felt most like myself:"}, {"id": "f3", "type": "textarea", "label": "One task I could move to a better hour next week:"}]'::jsonb, array['planning', 'self-monitoring']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('decision-pros-and-cons-grid-with-values-column', 'Decision Pros and Cons Grid With Values Column', 'worksheet'::resource_kind, 'A four-box grid that adds a column for what each choice says about the client''s values.', 'Use it to help a client weigh a choice beyond short-term relief.', array['Adults']::text[], '20 minutes', 'Fill in the grid in session on a real decision. The values column often shifts the talk from what feels safe to what matters. Notice where the client rushes; slow down on the box they skip.', '[{"id": "f0", "type": "textarea", "label": "The decision I am weighing:"}, {"id": "f1", "type": "textarea", "label": "Pros of choosing it, and cons:"}, {"id": "f2", "type": "textarea", "label": "Pros of not choosing it, and cons:"}, {"id": "f3", "type": "textarea", "label": "What each option says about what I care about:"}, {"id": "f4", "type": "textarea", "label": "The next small step I can take:"}]'::jsonb, array['values', 'planning']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('boundary-script-builder-page', 'Boundary Script Builder Page', 'worksheet'::resource_kind, 'Clients draft short, kind boundary sentences for situations they name.', 'Use it to help a client rehearse saying no in their own words.', array['Adults']::text[], '30 minutes', 'Pick one situation and draft two or three versions of the sentence, from softest to firmest. Read them aloud together and practice tone. Ask what the client fears happens after, and plan for it.', '[{"id": "f0", "type": "textarea", "label": "A situation where I need a boundary:"}, {"id": "f1", "type": "textarea", "label": "What I want to say in a single sentence:"}, {"id": "f2", "type": "textarea", "label": "A softer version and a firmer version:"}, {"id": "f3", "type": "textarea", "label": "What I might feel afterward and how I will care for myself:"}]'::jsonb, array['boundaries', 'communication']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('daily-small-wins-effort-ledger', 'Daily Small Wins Effort Ledger', 'worksheet'::resource_kind, 'A daily page for logging one thing that went acceptably, however small.', 'Use it to help a client notice effort they usually dismiss.', array['Adults']::text[], 'Five minutes daily for two weeks', 'Keep the ledger short so it survives a bad week. Review it in session by reading entries back and asking what the client did to make each one happen. Resist rewriting a small win into a bigger one.', '[{"id": "f0", "type": "textarea", "label": "Today''s small win:"}, {"id": "f1", "type": "textarea", "label": "What I did that helped it happen:"}, {"id": "f2", "type": "textarea", "label": "How it felt in my body:"}, {"id": "f3", "type": "textarea", "label": "Something I would like to repeat tomorrow:"}]'::jsonb, array['strengths', 'self-monitoring']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('transition-time-planning-sheet', 'Transition Time Planning Sheet', 'worksheet'::resource_kind, 'A sheet for planning the minutes between activities that tend to derail a day.', 'Use it to help a client smooth the handoffs between tasks.', array['Adults']::text[], '20 minutes', 'Help the client name the transitions that go badly, such as work to home. Design one tiny ritual for each, like a short walk or a glass of water. Test one ritual for a week before adding another.', '[{"id": "f0", "type": "textarea", "label": "The transition that is hardest for me:"}, {"id": "f1", "type": "textarea", "label": "What usually happens in those minutes:"}, {"id": "f2", "type": "textarea", "label": "A tiny ritual I could try:"}, {"id": "f3", "type": "textarea", "label": "How I will remind myself:"}]'::jsonb, array['routines', 'planning']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('thought-record-with-evidence-for-and-against-columns', 'Thought Record With Evidence For and Against Columns', 'cbt'::resource_kind, 'A seven-column thought record with a column for facts that fit and facts that do not.', 'Use it to help a client test a thought against what they actually know.', array['Adults']::text[], '25 minutes', 'Walk through one fresh entry in session before assigning it. Press gently for facts that a stranger could verify, separate from interpretations. End with a balanced statement in the client''s own words, not a slogan.', '[{"id": "f0", "type": "textarea", "label": "The situation:"}, {"id": "f1", "type": "textarea", "label": "The thought and how much I believe it (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "Facts that fit the thought:"}, {"id": "f3", "type": "textarea", "label": "Facts that do not fit it:"}, {"id": "f4", "type": "textarea", "label": "A balanced thought, and how much I believe it now:"}]'::jsonb, array['core CBT', 'thinking traps']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('mind-reading-check-card', 'Mind Reading Check Card', 'cbt'::resource_kind, 'A pocket card for catching guesses about what others think and checking them.', 'Use it to help a client separate a guess from a known fact.', array['Adults']::text[], '15 minutes', 'Introduce the card with a recent moment of feeling judged. Have the client list what they know, what they guessed and one way to check kindly. Many clients skip the checking step, so plan it in session.', '[{"id": "f0", "type": "textarea", "label": "What I think the other person is thinking:"}, {"id": "f1", "type": "textarea", "label": "What I actually know:"}, {"id": "f2", "type": "textarea", "label": "Other explanations that fit what I saw:"}, {"id": "f3", "type": "textarea", "label": "A kind way I could check:"}]'::jsonb, array['thinking traps', 'core CBT']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('prediction-test-planner-with-before-and-after-ratings', 'Prediction Test Planner With Before and After Ratings', 'cbt'::resource_kind, 'A planner to state a prediction, run a small test and record what happened.', 'Use it to help a client learn from outcomes instead of arguing with thoughts.', array['Adults']::text[], '30 minutes', 'Write the prediction as specifically as possible, with a rating of how sure the client is. Choose a test that is small and safe. After the experiment, compare the result with the prediction and ask what the client takes from it.', '[{"id": "f0", "type": "textarea", "label": "My prediction, and how sure I am (0 to 100):"}, {"id": "f1", "type": "textarea", "label": "The small test I will run and when:"}, {"id": "f2", "type": "textarea", "label": "What actually happened:"}, {"id": "f3", "type": "textarea", "label": "What I make of it, and my next experiment:"}]'::jsonb, array['behavioral experiment', 'core CBT']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('activity-and-mood-log-with-pleasure-and-mastery-ratings', 'Activity and Mood Log With Pleasure and Mastery Ratings', 'cbt'::resource_kind, 'An hourly log that rates how enjoyable and how accomplishing each activity felt.', 'Use it to show a client which activities lift or lower their day.', array['Adults']::text[], 'One week', 'Explain that the ratings are rough impressions, not scores. At review, look for activities with a good mood lift and plan more of them. Be curious about blank hours rather than critical.', '[{"id": "f0", "type": "textarea", "label": "Activities I did today, hour by hour:"}, {"id": "f1", "type": "textarea", "label": "Pleasure rating (0 to 10) for each:"}, {"id": "f2", "type": "textarea", "label": "Mastery rating (0 to 10) for each:"}, {"id": "f3", "type": "textarea", "label": "The activity I want more of next week:"}]'::jsonb, array['behavioral activation', 'self-monitoring']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('downward-arrow-belief-ladder-in-session', 'Downward Arrow Belief Ladder In Session', 'cbt'::resource_kind, 'A guided page that follows a thought down to the belief underneath it.', 'Use it to help a client name a belief they have been living by.', array['Adults']::text[], 'Full session', 'Use this in session, not as homework, since it can stir up strong feelings. Keep asking what it would mean if the thought were true until the client reaches a core statement. Close with a kinder alternative and a grounding moment.', '[{"id": "f0", "type": "textarea", "label": "The thought that bothers me:"}, {"id": "f1", "type": "textarea", "label": "If that were true, what would it mean about me?"}, {"id": "f2", "type": "textarea", "label": "And if that were true, what then?"}, {"id": "f3", "type": "textarea", "label": "The belief at the bottom, in my words:"}, {"id": "f4", "type": "textarea", "label": "A kinder belief I would like to build:"}]'::jsonb, array['core CBT', 'self-esteem']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('leaves-on-a-stream-noticing-log', 'Leaves on a Stream Noticing Log', 'act'::resource_kind, 'A log for practicing watching thoughts drift by and noticing what hooks the client.', 'Use it to give a client a repeatable way to practice defusion.', array['Adults']::text[], 'Ten minutes daily for two weeks', 'Lead the exercise once in session so the client hears the pacing. Some clients find imagery hard; offer a conveyor belt or clouds instead. The log tracks noticing, not success at clearing the mind.', '[{"id": "f0", "type": "textarea", "label": "Thoughts that floated by today:"}, {"id": "f1", "type": "textarea", "label": "The one that grabbed me and how I noticed:"}, {"id": "f2", "type": "textarea", "label": "What I did to let it drift:"}, {"id": "f3", "type": "textarea", "label": "How the practice felt in my body:"}]'::jsonb, array['defusion', 'mindfulness']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('weekly-four-area-values-compass', 'Weekly Four-Area Values Compass', 'act'::resource_kind, 'A weekly compass that rates action in four life areas against what matters.', 'Use it to help a client see where their days point and where they drift.', array['Adults']::text[], '20 minutes', 'Have the client choose four areas, rate how much they acted in line with each and name one small step. Remind them that values are directions, not goals to finish. Treat low ratings as information.', '[{"id": "f0", "type": "textarea", "label": "The four areas I chose:"}, {"id": "f1", "type": "textarea", "label": "How much I acted on each this week (0 to 10):"}, {"id": "f2", "type": "textarea", "label": "The area that pulled me most:"}, {"id": "f3", "type": "textarea", "label": "One small step for the week ahead:"}]'::jsonb, array['values', 'committed action']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('struggle-switch-worksheet', 'Struggle Switch Worksheet', 'act'::resource_kind, 'A page that maps the extra suffering that comes from fighting a feeling.', 'Use it to help a client see what struggling with a feeling costs them.', array['Adults']::text[], '25 minutes', 'Use the switch image to show that the first feeling and the fight against it are different things. Ask what the fight has cost and what the client might do with that energy. Avoid promising the feeling will shrink.', '[{"id": "f0", "type": "textarea", "label": "A feeling I have been fighting:"}, {"id": "f1", "type": "textarea", "label": "What I do to try to get rid of it:"}, {"id": "f2", "type": "textarea", "label": "What that fight costs me:"}, {"id": "f3", "type": "textarea", "label": "What I might do if I let the feeling be there:"}]'::jsonb, array['acceptance', 'willingness']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('self-as-context-observer-page-2', 'Self-as-Context Observer Page', 'act'::resource_kind, 'A page that practices noticing the part of the client that watches experience.', 'Use it to help a client step back from a story about themselves.', array['Adults']::text[], '20 minutes', 'Lead a brief observer exercise, then ask the client to write what the watching part notices. Some find it abstract, so use concrete examples like a changing mood watched by something steady. Keep it playful.', '[{"id": "f0", "type": "textarea", "label": "A story I tell about myself:"}, {"id": "f1", "type": "textarea", "label": "What the part of me that notices can see:"}, {"id": "f2", "type": "textarea", "label": "Things that change in me, and what stays the same:"}, {"id": "f3", "type": "textarea", "label": "How the story looks from the observer''s seat:"}]'::jsonb, array['mindfulness', 'acceptance']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('committed-action-barrier-planner', 'Committed Action Barrier Planner', 'act'::resource_kind, 'A planner that pairs a values-based action with the barriers and a plan for each.', 'Use it to help a client follow through when old habits push back.', array['Adults']::text[], '30 minutes', 'Choose one action small enough to do this week. List the thoughts and feelings that will show up, and decide in advance how the client will carry them along. Revisit the plan next session without blame.', '[{"id": "f0", "type": "textarea", "label": "The action I will take, and when:"}, {"id": "f1", "type": "textarea", "label": "The value behind it:"}, {"id": "f2", "type": "textarea", "label": "Thoughts and feelings likely to show up:"}, {"id": "f3", "type": "textarea", "label": "How I will carry them along while I act:"}]'::jsonb, array['committed action', 'values']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('tipp-body-reset-practice-card', 'TIPP Body Reset Practice Card', 'dbt'::resource_kind, 'A card listing temperature, intense exercise, paced breathing and muscle relaxation with a log.', 'Use it to give a client a fast body-based way to lower arousal.', array['Adults']::text[], '15 minutes', 'Teach each part in session and ask the client to try one before leaving. Check for health reasons to skip cold or exercise steps. The log helps the client find which parts suit them.', '[{"id": "f0", "type": "textarea", "label": "A time my feelings were too intense to think:"}, {"id": "f1", "type": "textarea", "label": "The TIPP part I tried:"}, {"id": "f2", "type": "textarea", "label": "My arousal before and after (0 to 10):"}, {"id": "f3", "type": "textarea", "label": "The part I will keep in my pocket:"}]'::jsonb, array['distress tolerance', 'core DBT']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('opposite-action-experiment-page', 'Opposite Action Experiment Page', 'dbt'::resource_kind, 'A page for choosing an urge, doing the opposite and recording what followed.', 'Use it to help a client test whether acting against an urge shifts the feeling.', array['Adults']::text[], '25 minutes', 'First check that the emotion does not fit the facts of the situation. Then plan the opposite action, including body posture and tone. Review honestly if it did not help; that is still data.', '[{"id": "f0", "type": "textarea", "label": "The emotion and its urge:"}, {"id": "f1", "type": "textarea", "label": "Does it fit the facts? What are the facts?"}, {"id": "f2", "type": "textarea", "label": "The opposite action I will try:"}, {"id": "f3", "type": "textarea", "label": "What happened to the feeling afterward:"}]'::jsonb, array['emotion regulation', 'core DBT']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('three-minds-decision-pause-sheet', 'Three Minds Decision Pause Sheet', 'dbt'::resource_kind, 'A short worksheet that sorts a choice into emotion mind, reasonable mind and wise mind.', 'Use it to help a client slow down a choice and check in with both voices.', array['Adults']::text[], '15 minutes', 'Use a recent decision and have the client write what each mind says. Then pause with a breath and ask what feels both true and workable. Do not push toward a particular answer.', '[{"id": "f0", "type": "textarea", "label": "The choice in front of me:"}, {"id": "f1", "type": "textarea", "label": "What emotion mind says:"}, {"id": "f2", "type": "textarea", "label": "What reasonable mind says:"}, {"id": "f3", "type": "textarea", "label": "What wise mind says after a pause:"}]'::jsonb, array['mindfulness', 'core DBT']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('pros-and-cons-of-acting-on-urges-page', 'Pros and Cons of Acting on Urges Page', 'dbt'::resource_kind, 'A grid comparing acting on an urge with resisting it, short term and long term.', 'Use it to help a client see the full picture before an urge peaks.', array['Adults']::text[], '20 minutes', 'Complete the grid during a calm moment, not at the peak of an urge. Put the page where the client can find it later. Where the urge involves substance use or self-harm, plan who to call and name 988 (call or text).', '[{"id": "f0", "type": "textarea", "label": "The urge I want to look at:"}, {"id": "f1", "type": "textarea", "label": "Short-term pros and cons of acting on it:"}, {"id": "f2", "type": "textarea", "label": "Short-term pros and cons of resisting it:"}, {"id": "f3", "type": "textarea", "label": "Long-term pros and cons of each:"}, {"id": "f4", "type": "textarea", "label": "If it feels unsafe, who I will call, and 988 (call or text):"}]'::jsonb, array['distress tolerance', 'urges']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('dear-man-rehearsal-sheet', 'DEAR MAN Rehearsal Sheet', 'dbt'::resource_kind, 'A scripted sheet for describing, expressing, asserting and reinforcing in a request.', 'Use it to help a client prepare a request they have been avoiding.', array['Adults']::text[], '30 minutes', 'Write each letter out for one real request, then role-play it with the client. Coach on staying on topic and holding a steady tone. Plan for a no and what the client will do with it.', '[{"id": "f0", "type": "textarea", "label": "The request I want to make:"}, {"id": "f1", "type": "textarea", "label": "Describe and express in my words:"}, {"id": "f2", "type": "textarea", "label": "Assert and reinforce in my words:"}, {"id": "f3", "type": "textarea", "label": "My plan if the answer is no:"}]'::jsonb, array['interpersonal effectiveness', 'communication']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('daily-appreciation-exchange', 'Daily Appreciation Exchange', 'couples'::resource_kind, 'Each partner writes one appreciation and shares it aloud every day for a week.', 'Use it to help partners notice what is working between them.', array['Couples']::text[], 'Five minutes daily for one week', 'Each partner has their own page. Ask partners to be specific and avoid a but. If one struggles to find anything, start with something small like making coffee. Review what it was like to receive one.', '[{"id": "f0", "type": "textarea", "label": "Partner A: Something I appreciated about my partner today:"}, {"id": "f1", "type": "textarea", "label": "Partner A: What it meant to me:"}, {"id": "f2", "type": "textarea", "label": "Partner B: Something I appreciated about my partner today:"}, {"id": "f3", "type": "textarea", "label": "Partner B: What it meant to me:"}]'::jsonb, array['connection', 'couples']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('fifteen-minute-couple-meeting-agenda', 'Fifteen-Minute Couple Meeting Agenda', 'couples'::resource_kind, 'A fifteen-minute agenda covering appreciation, logistics, feelings and one request.', 'Use it to give partners a steady time to talk before issues pile up.', array['Couples']::text[], '15 minutes weekly', 'Set a day and time and put it in both calendars. Each partner takes turns with the same four items. Coach them to stop at fifteen minutes even if something is unresolved, and to book a follow-up.', '[{"id": "f0", "type": "textarea", "label": "Both: What went well this week:"}, {"id": "f1", "type": "textarea", "label": "Partner A: A feeling and one request:"}, {"id": "f2", "type": "textarea", "label": "Partner B: A feeling and one request:"}, {"id": "f3", "type": "textarea", "label": "Both: What we agreed to try:"}]'::jsonb, array['communication', 'couples']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('repair-attempt-phrase-cards', 'Repair Attempt Phrase Cards', 'couples'::resource_kind, 'Partners choose and practice phrases that ease tension mid-argument.', 'Use it to help partners have words ready when talk turns sharp.', array['Couples']::text[], '25 minutes', 'Have each partner pick three phrases that would land well with them and share which ones help. Role-play using one mid-disagreement. Ask partners to accept a repair attempt when it is offered.', '[{"id": "f0", "type": "textarea", "label": "Partner A: Phrases that would help me:"}, {"id": "f1", "type": "textarea", "label": "Partner B: Phrases that would help me:"}, {"id": "f2", "type": "textarea", "label": "Both: A signal we will use to pause:"}, {"id": "f3", "type": "textarea", "label": "Both: How we will come back to the conversation:"}]'::jsonb, array['Gottman', 'communication']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('visible-and-invisible-tasks-fairness-map', 'Visible and Invisible Tasks Fairness Map', 'couples'::resource_kind, 'Partners list household and family tasks and talk through how they are divided.', 'Use it to help partners see and renegotiate who carries what.', array['Couples']::text[], '40 minutes', 'List tasks in three columns: visible, invisible and shared. Let each partner share how the split feels before proposing changes. Pick one change to test for two weeks and set a review date.', '[{"id": "f0", "type": "textarea", "label": "Both: Tasks we each do in a typical week:"}, {"id": "f1", "type": "textarea", "label": "Partner A: Tasks I carry that go unseen:"}, {"id": "f2", "type": "textarea", "label": "Partner B: Tasks I carry that go unseen:"}, {"id": "f3", "type": "textarea", "label": "Both: One change to test, and when we will review:"}]'::jsonb, array['relationship issues', 'planning']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('dream-within-conflict-conversation', 'Dream Within Conflict Conversation', 'couples'::resource_kind, 'Partners explore the hopes and stories beneath a recurring disagreement.', 'Use it to help partners hear what a stuck issue means to each of them.', array['Couples']::text[], 'Full session', 'Choose one recurring issue. Each partner takes a turn answering the prompts while the other listens without fixing. The therapist''s job is to slow the pace and help each person feel heard, not to settle the issue.', '[{"id": "f0", "type": "textarea", "label": "Partner A: What this issue means to me and where it comes from:"}, {"id": "f1", "type": "textarea", "label": "Partner A: What I hope for:"}, {"id": "f2", "type": "textarea", "label": "Partner B: What this issue means to me and where it comes from:"}, {"id": "f3", "type": "textarea", "label": "Partner B: What I hope for:"}]'::jsonb, array['Gottman', 'connection']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('weather-window-feelings-frame', 'Weather Window Feelings Frame', 'kids'::resource_kind, 'Children decorate a paper window showing today''s feelings as weather.', 'Use it to help a child show feelings without needing the words.', array['Children']::text[], '30 minutes', 'Give paper, crayons and a cut-out frame. The child draws weather for each feeling and explains it if they wish. The parent asks one curious question and listens without fixing. Keep it playful.', '[{"id": "f0", "type": "textarea", "label": "The weather inside me today:"}, {"id": "f1", "type": "textarea", "label": "Why my weather looks like this:"}, {"id": "f2", "type": "textarea", "label": "What helps when it storms:"}, {"id": "f3", "type": "textarea", "label": "What my grown-up noticed:"}]'::jsonb, array['children', 'art']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('feed-the-worry-box-monster-craft', 'Feed the Worry Box Monster Craft', 'kids'::resource_kind, 'Children build a box monster that holds written worries for a set time.', 'Use it to give a child a place to put worries so they can play.', array['Children']::text[], '40 minutes', 'Decorate a shoebox with a mouth slot. The child writes or draws a worry and feeds it in. The parent checks the box at an agreed time and talks about one worry together. Keep the tone friendly.', '[{"id": "f0", "type": "textarea", "label": "A worry I fed to the monster:"}, {"id": "f1", "type": "textarea", "label": "What my monster looks like:"}, {"id": "f2", "type": "textarea", "label": "When we will open the box:"}, {"id": "f3", "type": "textarea", "label": "What my grown-up said that helped:"}]'::jsonb, array['children', 'worry']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('calm-down-jar-building-day', 'Calm Down Jar Building Day', 'kids'::resource_kind, 'Children fill a jar with glitter and water to watch while they breathe.', 'Use it to teach a child a visual way to settle.', array['Children']::text[], '30 minutes', 'Make the jar together, with glue to seal the lid. The child shakes it and breathes while the glitter settles. The parent models the same breathing alongside. Use the jar before upsets, not as a time-out.', '[{"id": "f0", "type": "textarea", "label": "How I felt when I shook the jar:"}, {"id": "f1", "type": "textarea", "label": "How I felt when the glitter settled:"}, {"id": "f2", "type": "textarea", "label": "Where we will keep the jar:"}, {"id": "f3", "type": "textarea", "label": "When I will use it:"}]'::jsonb, array['children', 'regulation']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('brave-steps-footprint-path', 'Brave Steps Footprint Path', 'kids'::resource_kind, 'Children trace footprints on paper for each small brave step they take.', 'Use it to help a child see their own courage grow in small pieces.', array['Children']::text[], 'One week', 'Cut out footprints and let the child color them. Each brave step earns one footprint on the path. The parent writes what the child did, in the child''s words, and celebrates quietly.', '[{"id": "f0", "type": "textarea", "label": "A brave step I took:"}, {"id": "f1", "type": "textarea", "label": "How I felt before and after:"}, {"id": "f2", "type": "textarea", "label": "Who saw me do it:"}, {"id": "f3", "type": "textarea", "label": "The next footprint I want to add:"}]'::jsonb, array['children', 'strengths']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('kindness-coupon-booklet', 'Kindness Coupon Booklet', 'kids'::resource_kind, 'Children make coupons of kind acts to give family members.', 'Use it to help a child practice warm giving and see how it lands.', array['Children']::text[], '40 minutes', 'Staple paper into a booklet and have the child draw each coupon. The parent redeems one and says how it felt. Pick acts that are small and free, like a hug or a drawing.', '[{"id": "f0", "type": "textarea", "label": "Kind acts I will give:"}, {"id": "f1", "type": "textarea", "label": "Who gets each coupon:"}, {"id": "f2", "type": "textarea", "label": "How I felt when someone used one:"}, {"id": "f3", "type": "textarea", "label": "A new coupon I want to add:"}]'::jsonb, array['children', 'connection']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('feelings-mime-and-guess-round', 'Feelings Mime and Guess Round', 'game'::resource_kind, 'Players act out feelings without words while others guess.', 'Use it to help a group practice reading feelings in faces and bodies.', array['Groups']::text[], '20 minutes', 'Write feelings on slips and let players draw one. Others guess, then the actor says what they did with their face and body. Afterward, debrief on which cues were easiest to read and which felt confusing.', '[{"id": "f0", "type": "textarea", "label": "A feeling I acted out and how:"}, {"id": "f1", "type": "textarea", "label": "A feeling that was hard to guess:"}, {"id": "f2", "type": "textarea", "label": "What cues I notice in others:"}, {"id": "f3", "type": "textarea", "label": "One thing I will watch for this week:"}]'::jsonb, array['game', 'emotion identification']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('strength-naming-circle-round', 'Strength Naming Circle Round', 'game'::resource_kind, 'Players take turns naming a strength they see in the person on their left.', 'Use it to help a group give and receive specific, honest praise.', array['Groups']::text[], '25 minutes', 'Pass a talking object. The speaker names a strength and a moment they saw it. The receiver says thank you and nothing else. In the debrief, ask what it was like to take it in.', '[{"id": "f0", "type": "textarea", "label": "A strength someone named in me:"}, {"id": "f1", "type": "textarea", "label": "How it felt to hear it:"}, {"id": "f2", "type": "textarea", "label": "A strength I named in someone else:"}, {"id": "f3", "type": "textarea", "label": "One strength I want to use this week:"}]'::jsonb, array['game', 'strengths']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('coping-cards-go-fish', 'Coping Cards Go Fish', 'game'::resource_kind, 'A card game where players ask for coping skills to match a feeling.', 'Use it to help a group learn the names and uses of many coping skills.', array['Groups']::text[], '25 minutes', 'Make a deck of paired cards, a feeling and a skill that fits it. Play like go fish. When a pair is made, the player explains when they would use it. Debrief on which skills they would try.', '[{"id": "f0", "type": "textarea", "label": "Skill pairs I collected:"}, {"id": "f1", "type": "textarea", "label": "A skill I had not heard of:"}, {"id": "f2", "type": "textarea", "label": "One I will try this week and when:"}, {"id": "f3", "type": "textarea", "label": "How the game felt:"}]'::jsonb, array['game', 'coping skills']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('pass-the-pause-beanbag', 'Pass the Pause Beanbag', 'game'::resource_kind, 'Players toss a beanbag and answer a prompt only after taking one slow breath.', 'Use it to help a group practice pausing before responding.', array['Groups']::text[], '15 minutes', 'Stand in a circle. The catcher takes a breath, then answers a prompt such as a place where they feel calm. Add speed rounds so players notice how hard pausing gets when rushed. Debrief afterward.', '[{"id": "f0", "type": "textarea", "label": "How the pause felt in my body:"}, {"id": "f1", "type": "textarea", "label": "When it was hardest to wait:"}, {"id": "f2", "type": "textarea", "label": "A moment this week I could use a pause:"}, {"id": "f3", "type": "textarea", "label": "What I noticed in others:"}]'::jsonb, array['game', 'regulation']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('values-coin-auction-with-debrief-round', 'Values Coin Auction With Debrief Round', 'game'::resource_kind, 'Players bid pretend coins on values cards to see what they most want to hold.', 'Use it to help a group clarify what they care about most.', array['Groups']::text[], '30 minutes', 'Give each player the same coins and a set of values cards. Run the auction and watch for surprise bids. In the debrief, ask what they gave up and what they would do with the values they won.', '[{"id": "f0", "type": "textarea", "label": "The value I spent the most on and why:"}, {"id": "f1", "type": "textarea", "label": "A value I wished I had won:"}, {"id": "f2", "type": "textarea", "label": "What surprised me about my bids:"}, {"id": "f3", "type": "textarea", "label": "One action I can take on my top value this week:"}]'::jsonb, array['game', 'values']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('safe-anchors-inventory-page', 'Safe Anchors Inventory Page', 'worksheet'::resource_kind, 'Clients list real and imagined places, objects and people that bring a sense of safety.', 'Use it to help a client build a stabilizing set of safe anchors.', array['Adults']::text[], '25 minutes', 'Keep this to the present and the stabilizing side. Invite the client to note sensory details of each safe anchor and rate how settled they feel. Do not ask for accounts of past events; if distress rises, pause and ground together.', '[{"id": "f0", "type": "textarea", "label": "A place where I feel safe or calmer:"}, {"id": "f1", "type": "textarea", "label": "What I see, hear and feel there:"}, {"id": "f2", "type": "textarea", "label": "A person or object that helps me feel steady:"}, {"id": "f3", "type": "textarea", "label": "How settled I feel now (0 to 10):"}]'::jsonb, array['PTSD and trauma', 'safety', 'grounding']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('trigger-reminder-versus-danger-now-card', 'Trigger Reminder Versus Danger Now Card', 'cbt'::resource_kind, 'A card for sorting a reminder from a present danger.', 'Use it to help a client check what is happening now against what a reminder stirs.', array['Adults']::text[], '20 minutes', 'Practice the card in session with a mild everyday reminder, never a detailed memory. The client names what their senses say is true right now. Keep the focus on the present and on pacing.', '[{"id": "f0", "type": "textarea", "label": "A reminder that stirred me today:"}, {"id": "f1", "type": "textarea", "label": "What my body did:"}, {"id": "f2", "type": "textarea", "label": "What is happening right now around me:"}, {"id": "f3", "type": "textarea", "label": "A calming thing I can say to myself:"}]'::jsonb, array['PTSD and trauma', 'grounding', 'core CBT']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('making-room-for-hard-feelings-gently-page', 'Making Room for Hard Feelings Gently Page', 'act'::resource_kind, 'A page for sitting with a feeling at a safe distance while doing something that matters.', 'Use it to help a client carry hard feelings without being pushed to revisit events.', array['Adults']::text[], '20 minutes', 'Anchor the exercise in present values and small actions, with the feeling kept at a tolerable size. Agree on a stop signal. The client chooses how close to go and never has to describe what happened.', '[{"id": "f0", "type": "textarea", "label": "A value I want to live by this week:"}, {"id": "f1", "type": "textarea", "label": "A feeling that comes along with it:"}, {"id": "f2", "type": "textarea", "label": "How I can keep the feeling at a distance I can manage:"}, {"id": "f3", "type": "textarea", "label": "A small action I will take anyway:"}]'::jsonb, array['PTSD and trauma', 'acceptance', 'values']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('self-soothing-with-the-five-senses-plan', 'Self-Soothing With the Five Senses Plan', 'dbt'::resource_kind, 'A sensory plan that gathers soothing items for sight, sound, smell, taste and touch.', 'Use it to give a client a ready kit for moments of overwhelm.', array['Adults']::text[], '25 minutes', 'Build the kit together and test one item in session. Check that a scent or sound is not itself a reminder for the client. Review which items helped and swap out the rest.', '[{"id": "f0", "type": "textarea", "label": "Something soothing to look at:"}, {"id": "f1", "type": "textarea", "label": "Something soothing to hear:"}, {"id": "f2", "type": "textarea", "label": "Something soothing to smell or taste:"}, {"id": "f3", "type": "textarea", "label": "Something soothing to touch:"}, {"id": "f4", "type": "textarea", "label": "Where I will keep my kit:"}]'::jsonb, array['PTSD and trauma', 'distress tolerance', 'grounding']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('partner-plan-for-overwhelm-without-questions', 'Partner Plan for Overwhelm Without Questions', 'couples'::resource_kind, 'Partners agree on what helps and what to avoid when one is overwhelmed.', 'Use it to help a partner offer steady support without pressing for details.', array['Couples']::text[], '40 minutes', 'Each partner writes their part. The affected partner says what helps, what does not and how to ask for space. The other partner does not need to hear what happened. Agree on a word for a pause.', '[{"id": "f0", "type": "textarea", "label": "Partner A: What helps when I am overwhelmed:"}, {"id": "f1", "type": "textarea", "label": "Partner A: What does not help:"}, {"id": "f2", "type": "textarea", "label": "Partner B: What I can offer and what I will avoid:"}, {"id": "f3", "type": "textarea", "label": "Both: Our word for a pause:"}]'::jsonb, array['PTSD and trauma', 'support', 'couples']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('worry-time-clock-craft', 'Worry Time Clock Craft', 'kids'::resource_kind, 'Children make a paper clock that marks a short daily worry time.', 'Use it to help a child contain worries to a set little window.', array['Children']::text[], '30 minutes', 'Build the clock with a moving hand and pick a ten-minute worry time with the parent. Worries that pop up are jotted down and held until then. The parent listens during worry time and then moves on to something fun.', '[{"id": "f0", "type": "textarea", "label": "A worry I saved for worry time:"}, {"id": "f1", "type": "textarea", "label": "When our worry time is:"}, {"id": "f2", "type": "textarea", "label": "What I did while I waited:"}, {"id": "f3", "type": "textarea", "label": "What I did after worry time:"}]'::jsonb, array['anxiety', 'children', 'worry']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('uncertainty-dice-experiments', 'Uncertainty Dice Experiments', 'game'::resource_kind, 'Players roll dice to pick a small uncertain activity to try.', 'Use it to help a group practice tolerating not knowing in small steps.', array['Groups']::text[], '30 minutes', 'Write six mild uncertain tasks on a card, such as taking a new route. Players roll, do the task and report. In the debrief, compare what they predicted with what happened.', '[{"id": "f0", "type": "textarea", "label": "The task I rolled:"}, {"id": "f1", "type": "textarea", "label": "What I expected to happen:"}, {"id": "f2", "type": "textarea", "label": "What really happened:"}, {"id": "f3", "type": "textarea", "label": "What I learned about not knowing:"}]'::jsonb, array['anxiety', 'game', 'behavioral experiment']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('avoidance-trade-off-ledger-with-small-step', 'Avoidance Trade-Off Ledger With Small Step', 'worksheet'::resource_kind, 'A ledger of what the client skips, what it saves and what it costs.', 'Use it to help a client see the trade they make when they avoid.', array['Adults']::text[], '25 minutes', 'List avoided situations without judgment. Add the relief gained now and the cost over time. Pick one entry the client might approach with a small step.', '[{"id": "f0", "type": "textarea", "label": "Something I have been avoiding:"}, {"id": "f1", "type": "textarea", "label": "What avoiding gives me:"}, {"id": "f2", "type": "textarea", "label": "What avoiding costs me:"}, {"id": "f3", "type": "textarea", "label": "A small step toward it:"}]'::jsonb, array['anxiety', 'avoidance', 'self-monitoring']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('worry-probability-and-coping-page', 'Worry Probability and Coping Page', 'cbt'::resource_kind, 'A page that estimates how likely a feared outcome is and what the client would do if it happened.', 'Use it to help a client balance likelihood against their own coping.', array['Adults']::text[], '25 minutes', 'Ask for the worry in one sentence, then estimate how likely it is and what the client could do. Many clients spend all their effort on the likelihood; spend equal time on coping.', '[{"id": "f0", "type": "textarea", "label": "The worry in one sentence:"}, {"id": "f1", "type": "textarea", "label": "How likely I think it is (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "What I could do if it happened:"}, {"id": "f3", "type": "textarea", "label": "What I would say to a friend with this worry:"}]'::jsonb, array['anxiety', 'worry', 'core CBT']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('anxiety-as-passenger-bus-page', 'Anxiety as Passenger Bus Page', 'act'::resource_kind, 'A page using the passengers-on-the-bus image for carrying anxiety while driving toward values.', 'Use it to help a client keep driving with worry along for the ride.', array['Adults']::text[], '25 minutes', 'Draw the bus together with the client at the wheel and anxiety as one noisy passenger. Name where the client wants to drive. Ask what the passenger shouts and how the client can answer without stopping.', '[{"id": "f0", "type": "textarea", "label": "Where I want to drive my bus:"}, {"id": "f1", "type": "textarea", "label": "What the anxious passenger says:"}, {"id": "f2", "type": "textarea", "label": "How I can answer and keep driving:"}, {"id": "f3", "type": "textarea", "label": "One turn I will take this week:"}]'::jsonb, array['anxiety', 'defusion', 'values']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('building-mastery-daily-tick-list', 'Building Mastery Daily Tick List', 'dbt'::resource_kind, 'A short list of doable tasks that give a sense of accomplishment.', 'Use it to help a client rebuild a sense of capability one task at a time.', array['Adults']::text[], 'Five minutes daily for two weeks', 'Choose tasks that are small and reachable. The client ticks them and notes how it felt. Check in on safety at each visit; where the client mentions harming themselves, review the safety plan and name 988 (call or text).', '[{"id": "f0", "type": "textarea", "label": "Tasks I chose for this week:"}, {"id": "f1", "type": "textarea", "label": "The one I felt best about finishing:"}, {"id": "f2", "type": "textarea", "label": "How I felt after I did it:"}, {"id": "f3", "type": "textarea", "label": "If dark thoughts grow, who I will tell, and 988 (call or text):"}]'::jsonb, array['depression', 'emotion regulation', 'core DBT']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('partner-check-in-on-low-days', 'Partner Check-In on Low Days', 'couples'::resource_kind, 'Partners agree on how to ask about and respond to low days.', 'Use it to help partners support each other without pressure or blame.', array['Couples']::text[], '30 minutes', 'Each partner shares what is helpful and unhelpful on a low day. Agree on a simple signal and one offer of help. Remind the partner that they are not responsible for fixing the mood.', '[{"id": "f0", "type": "textarea", "label": "Partner A: What helps me on a low day:"}, {"id": "f1", "type": "textarea", "label": "Partner A: What I find hard to hear:"}, {"id": "f2", "type": "textarea", "label": "Partner B: What I can offer without fixing:"}, {"id": "f3", "type": "textarea", "label": "Both: Our signal and our plan:"}]'::jsonb, array['depression', 'support', 'couples']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('mood-flower-garden-drawing', 'Mood Flower Garden Drawing', 'kids'::resource_kind, 'Children draw a garden where flowers show feelings and what helps them grow.', 'Use it to help a child talk about low and bright days.', array['Children']::text[], '35 minutes', 'Provide paper and crayons. Each flower stands for a feeling and the child adds sun, rain or water for what helps. The parent asks which flower needs care. If a child says they want to hurt themselves, follow your safety steps and reporting duties.', '[{"id": "f0", "type": "textarea", "label": "The flowers in my garden:"}, {"id": "f1", "type": "textarea", "label": "What helps them grow:"}, {"id": "f2", "type": "textarea", "label": "What my garden needs today:"}, {"id": "f3", "type": "textarea", "label": "What my grown-up can do to help:"}]'::jsonb, array['depression', 'children', 'art']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('energy-tokens-spend-and-save-board', 'Energy Tokens Spend and Save Board', 'game'::resource_kind, 'Players spend and earn energy tokens by choosing activities.', 'Use it to help a group see how activities give and take energy.', array['Groups']::text[], '30 minutes', 'Give each player ten tokens. Activity cards cost or add tokens, and players choose to keep a reserve. Debrief on which activities refilled them and which drained them.', '[{"id": "f0", "type": "textarea", "label": "Activities that refilled my bank:"}, {"id": "f1", "type": "textarea", "label": "Activities that drained it:"}, {"id": "f2", "type": "textarea", "label": "What I will schedule more of:"}, {"id": "f3", "type": "textarea", "label": "What I will plan around:"}]'::jsonb, array['depression', 'game', 'behavioral activation']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('gratitude-of-small-comforts-page', 'Gratitude of Small Comforts Page', 'worksheet'::resource_kind, 'A page for noticing small comforts in a day without forcing positivity.', 'Use it to help a client notice comfort alongside heavy feelings.', array['Adults']::text[], 'Five minutes daily for one week', 'Frame it as noticing, not cheering up. Accept small, flat entries. If the client writes nothing, explore that gently rather than pushing.', '[{"id": "f0", "type": "textarea", "label": "A small comfort I noticed today:"}, {"id": "f1", "type": "textarea", "label": "What made it possible:"}, {"id": "f2", "type": "textarea", "label": "Where I felt it in my body:"}, {"id": "f3", "type": "textarea", "label": "How heavy the day felt (0 to 10):"}]'::jsonb, array['depression', 'self-compassion', 'self-monitoring']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('task-breakdown-into-tiny-steps-page', 'Task Breakdown Into Tiny Steps Page', 'cbt'::resource_kind, 'A page for splitting a task into steps that each take five minutes or less.', 'Use it to help a client start tasks that feel too big to begin.', array['Adults']::text[], '25 minutes', 'Choose a real task. Break it down until the first step is almost silly. Add a start cue and a visible place to tick steps off.', '[{"id": "f0", "type": "textarea", "label": "The task I keep putting off:"}, {"id": "f1", "type": "textarea", "label": "Its first five-minute step:"}, {"id": "f2", "type": "textarea", "label": "The next three steps:"}, {"id": "f3", "type": "textarea", "label": "My cue to start, and where I will tick steps off:"}]'::jsonb, array['ADHD', 'planning', 'routines']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('dull-task-to-value-bridge-sheet', 'Dull Task to Value Bridge Sheet', 'act'::resource_kind, 'A page linking tasks that feel dull to values the client cares about.', 'Use it to help a client find a reason to begin that is more than interest.', array['Adults']::text[], '20 minutes', 'Take one dull task and ask what it serves. The reason becomes a short phrase the client keeps visible. Pair it with a small reward after.', '[{"id": "f0", "type": "textarea", "label": "A task that feels dull:"}, {"id": "f1", "type": "textarea", "label": "What it connects to that I care about:"}, {"id": "f2", "type": "textarea", "label": "A short phrase to remind myself:"}, {"id": "f3", "type": "textarea", "label": "A small reward after I finish:"}]'::jsonb, array['ADHD', 'values', 'committed action']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('mindful-pause-before-acting-card', 'Mindful Pause Before Acting Card', 'dbt'::resource_kind, 'A card for building a short pause between a spark of impulse and action.', 'Use it to help a client practice a one-breath pause.', array['Adults']::text[], '20 minutes', 'Rehearse the pause with a low-stakes choice in session. The client sets a cue for it. Count it as success whenever it happens, however short.', '[{"id": "f0", "type": "textarea", "label": "A moment I act fast:"}, {"id": "f1", "type": "textarea", "label": "My one-breath pause cue:"}, {"id": "f2", "type": "textarea", "label": "What I noticed when I paused:"}, {"id": "f3", "type": "textarea", "label": "Where I will practice this week:"}]'::jsonb, array['ADHD', 'mindfulness', 'core DBT']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('household-systems-and-reminders-agreement', 'Household Systems and Reminders Agreement', 'couples'::resource_kind, 'Partners design reminders and shared systems without nagging.', 'Use it to help partners lean on systems instead of memory and blame.', array['Couples']::text[], '40 minutes', 'Each partner names tasks that slip and reminders that feel supportive rather than critical. Agree on one visible system, like a shared calendar. Review in two weeks.', '[{"id": "f0", "type": "textarea", "label": "Partner A: Tasks that slip and a reminder that would help:"}, {"id": "f1", "type": "textarea", "label": "Partner B: What I need to keep from nagging:"}, {"id": "f2", "type": "textarea", "label": "Both: Our shared system:"}, {"id": "f3", "type": "textarea", "label": "Both: When we will review it:"}]'::jsonb, array['ADHD', 'routines', 'couples']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('chore-chart-rocket-ship-craft', 'Chore Chart Rocket Ship Craft', 'kids'::resource_kind, 'Children build a rocket chart where each step moves the ship forward.', 'Use it to make morning or bedtime steps visible and fun.', array['Children']::text[], '35 minutes', 'Draw a rocket with steps up the side. The child picks stickers and the parent points to the chart without repeating requests. Keep steps few and clear.', '[{"id": "f0", "type": "textarea", "label": "The steps on my rocket:"}, {"id": "f1", "type": "textarea", "label": "The sticker I picked:"}, {"id": "f2", "type": "textarea", "label": "The step that is hardest:"}, {"id": "f3", "type": "textarea", "label": "How my grown-up will help me remember:"}]'::jsonb, array['ADHD', 'children', 'routines']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('urge-wave-rating-card-game', 'Urge Wave Rating Card Game', 'game'::resource_kind, 'Players ride cards that rise and fall like waves and name what they notice.', 'Use it to help a group practice watching an urge pass.', array['Groups']::text[], '25 minutes', 'Players draw an urge card and rate it, then talk through what helps it ease as the rating falls. In the debrief, ask what each learned about how urges rise and pass.', '[{"id": "f0", "type": "textarea", "label": "An urge I rode out:"}, {"id": "f1", "type": "textarea", "label": "How strong it got and how it changed:"}, {"id": "f2", "type": "textarea", "label": "What I did while it passed:"}, {"id": "f3", "type": "textarea", "label": "What I will remember next time:"}]'::jsonb, array['addiction', 'urges', 'game']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('substance-use-trigger-and-plan-page', 'Substance Use Trigger and Plan Page', 'worksheet'::resource_kind, 'A page mapping triggers to a plan B for each.', 'Use it to help a client prepare for moments when urges are likely.', array['Adults']::text[], '25 minutes', 'List triggers by place, people, feelings and times. Give each a specific alternative and a person to contact. Review often and update after slips without blame.', '[{"id": "f0", "type": "textarea", "label": "Triggers for substance use:"}, {"id": "f1", "type": "textarea", "label": "My plan for each:"}, {"id": "f2", "type": "textarea", "label": "People I can reach:"}, {"id": "f3", "type": "textarea", "label": "What I will do if a slip happens:"}]'::jsonb, array['addiction', 'urges', 'planning']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('thoughts-that-ride-with-an-urge-record', 'Thoughts That Ride With an Urge Record', 'cbt'::resource_kind, 'A thought record for the thoughts that arrive with an urge.', 'Use it to help a client examine thoughts that push toward substance use.', array['Adults']::text[], '25 minutes', 'Use it in the moment or soon after. The client notes the thought, the urge strength and a balanced response. Compare the urge before and after.', '[{"id": "f0", "type": "textarea", "label": "The situation and urge (0 to 10):"}, {"id": "f1", "type": "textarea", "label": "The thought that came with it:"}, {"id": "f2", "type": "textarea", "label": "A balanced response:"}, {"id": "f3", "type": "textarea", "label": "Urge strength afterward (0 to 10):"}]'::jsonb, array['addiction', 'urges', 'core CBT']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('life-values-beyond-substance-use-sheet', 'Life Values Beyond Substance Use Sheet', 'act'::resource_kind, 'A page naming what matters most and actions that fit it.', 'Use it to help a client reconnect with reasons for change.', array['Adults']::text[], '25 minutes', 'Start with what the client wants their life to include. Link each value to one small action this week. Treat urges as passengers.', '[{"id": "f0", "type": "textarea", "label": "What I want my life to hold:"}, {"id": "f1", "type": "textarea", "label": "Actions that fit those values:"}, {"id": "f2", "type": "textarea", "label": "An urge that may show up and how I will carry it:"}, {"id": "f3", "type": "textarea", "label": "One step this week:"}]'::jsonb, array['addiction', 'values', 'urges']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('crisis-survival-skills-for-urges-plan', 'Crisis Survival Skills for Urges Plan', 'dbt'::resource_kind, 'A plan combining distraction, self-soothing and improving the moment for urges.', 'Use it to give a client skills to wait out an urge.', array['Adults']::text[], '25 minutes', 'Build the plan with at least three skills per category. The client chooses which ones feel doable. If the urge ties to self-harm, name 988 (call or text) on the page.', '[{"id": "f0", "type": "textarea", "label": "Ways I can distract myself:"}, {"id": "f1", "type": "textarea", "label": "Ways I can soothe myself:"}, {"id": "f2", "type": "textarea", "label": "Ways I can improve the moment:"}, {"id": "f3", "type": "textarea", "label": "Who to call, and 988 (call or text):"}]'::jsonb, array['addiction', 'distress tolerance', 'urges']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('anger-time-out-agreement-for-couples', 'Anger Time-Out Agreement for Couples', 'couples'::resource_kind, 'Partners agree on how to pause a heated talk and return to it.', 'Use it to help partners cool down without leaving the other alone.', array['Couples']::text[], '35 minutes', 'Each partner picks a signal and a time to return. Practice calling one in session. The one who calls it says when they will return and keeps their word.', '[{"id": "f0", "type": "textarea", "label": "Partner A: How I know I am heating up:"}, {"id": "f1", "type": "textarea", "label": "Partner B: How I know I am heating up:"}, {"id": "f2", "type": "textarea", "label": "Both: Our signal and return time:"}, {"id": "f3", "type": "textarea", "label": "Both: What we will do in the break:"}]'::jsonb, array['anger management', 'boundaries', 'couples']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('volcano-cooling-craft', 'Volcano Cooling Craft', 'kids'::resource_kind, 'Children build a volcano model and map warning signs and cool-down steps.', 'Use it to help a child notice anger early and choose a cool-down.', array['Children']::text[], '40 minutes', 'Build a simple model with paper and mark body signs on the slopes. The child picks cool-down steps and the parent practices one alongside them. Praise using the step, not the calm.', '[{"id": "f0", "type": "textarea", "label": "Signs my volcano is heating up:"}, {"id": "f1", "type": "textarea", "label": "What I can do to cool it:"}, {"id": "f2", "type": "textarea", "label": "What I did last time:"}, {"id": "f3", "type": "textarea", "label": "How my grown-up will help:"}]'::jsonb, array['anger management', 'children', 'regulation']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('anger-thermometer-spin-game', 'Anger Thermometer Spin Game', 'game'::resource_kind, 'Players spin for a scenario and place it on an anger thermometer.', 'Use it to help a group rate anger and choose steps for each level.', array['Groups']::text[], '25 minutes', 'Prepare scenarios and a thermometer. Players place the scene and name one step that fits. Debrief on how the same event rates differently for each person.', '[{"id": "f0", "type": "textarea", "label": "A scenario I rated:"}, {"id": "f1", "type": "textarea", "label": "Where I put it and why:"}, {"id": "f2", "type": "textarea", "label": "The step I would choose:"}, {"id": "f3", "type": "textarea", "label": "How others rated it differently:"}]'::jsonb, array['anger management', 'game', 'regulation']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('anger-cost-and-choice-page', 'Anger Cost and Choice Page', 'worksheet'::resource_kind, 'A page that lists what anger costs and what the client wants instead.', 'Use it to help a client choose a response before the peak.', array['Adults']::text[], '25 minutes', 'Without shaming, help the client list recent episodes, costs and what they wanted. Build one alternative response.', '[{"id": "f0", "type": "textarea", "label": "A recent time I got angry:"}, {"id": "f1", "type": "textarea", "label": "What it cost me:"}, {"id": "f2", "type": "textarea", "label": "What I really wanted:"}, {"id": "f3", "type": "textarea", "label": "A different response I can try:"}]'::jsonb, array['anger management', 'values', 'self-monitoring']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('hot-thought-catcher-page', 'Hot Thought Catcher Page', 'cbt'::resource_kind, 'A page that finds the thought fueling anger and tests it.', 'Use it to help a client slow down angry thinking.', array['Adults']::text[], '25 minutes', 'Look for shoulds and personal slights. Ask what else might be true. Find a calmer, balanced statement that is still assertive.', '[{"id": "f0", "type": "textarea", "label": "What happened:"}, {"id": "f1", "type": "textarea", "label": "The hot thought:"}, {"id": "f2", "type": "textarea", "label": "Other ways to see it:"}, {"id": "f3", "type": "textarea", "label": "A calmer, balanced thought:"}]'::jsonb, array['anger management', 'thinking traps', 'core CBT']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('checking-urge-as-a-pull-page', 'Checking Urge as a Pull Page', 'act'::resource_kind, 'A page that notices the pull to check and chooses a values-based action.', 'Use it to help a client carry the urge without acting on it.', array['Adults']::text[], '25 minutes', 'Work at a pace the client sets. Name the urge as a pull, not a command. Pair with a value and a small action. Not a replacement for any exposure work the clinician judges suitable.', '[{"id": "f0", "type": "textarea", "label": "The urge I noticed:"}, {"id": "f1", "type": "textarea", "label": "The thought that came with it:"}, {"id": "f2", "type": "textarea", "label": "What I did with my hands and attention instead:"}, {"id": "f3", "type": "textarea", "label": "The value I acted on:"}]'::jsonb, array['OCD', 'defusion', 'values']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('radical-acceptance-of-uncertainty-page', 'Radical Acceptance of Uncertainty Page', 'dbt'::resource_kind, 'A page for practicing acceptance of what cannot be known.', 'Use it to help a client turn toward uncertainty with willingness.', array['Adults']::text[], '20 minutes', 'Name something uncertain and practice a short acceptance statement with breathing. Check that the practice is not being used as another way to seek certainty.', '[{"id": "f0", "type": "textarea", "label": "Something uncertain right now:"}, {"id": "f1", "type": "textarea", "label": "The urge to find out for sure:"}, {"id": "f2", "type": "textarea", "label": "An acceptance phrase I can use:"}, {"id": "f3", "type": "textarea", "label": "How my body felt after:"}]'::jsonb, array['OCD', 'acceptance', 'core DBT']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('reassurance-agreement-for-couples', 'Reassurance Agreement for Couples', 'couples'::resource_kind, 'Partners agree on how to respond to requests for reassurance.', 'Use it to help partners support without feeding the cycle.', array['Couples']::text[], '35 minutes', 'Together define a kind, short reply that doesn''t repeat. The partner offers support in other ways. Review how it feels for each person.', '[{"id": "f0", "type": "textarea", "label": "Partner A: When I ask for reassurance I feel:"}, {"id": "f1", "type": "textarea", "label": "Partner B: When I am asked, I feel:"}, {"id": "f2", "type": "textarea", "label": "Both: Our kind short reply:"}, {"id": "f3", "type": "textarea", "label": "Both: Other ways to support:"}]'::jsonb, array['OCD', 'support', 'couples']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('bossy-brain-naming-and-talking-back-drawing', 'Bossy Brain Naming and Talking-Back Drawing', 'kids'::resource_kind, 'Children name and draw the worry voice that bosses them around.', 'Use it to help a child separate themselves from the worry voice.', array['Children']::text[], '30 minutes', 'Give the worry a silly name and draw it. The child writes back to it. The parent practices not joining in when it demands rituals, and praises effort.', '[{"id": "f0", "type": "textarea", "label": "My bossy brain''s name:"}, {"id": "f1", "type": "textarea", "label": "What it tells me to do:"}, {"id": "f2", "type": "textarea", "label": "What I tell it back:"}, {"id": "f3", "type": "textarea", "label": "How my grown-up helps:"}]'::jsonb, array['OCD', 'children', 'defusion']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('unsure-is-okay-challenge-cards', 'Unsure Is Okay Challenge Cards', 'game'::resource_kind, 'Players draw small cards that ask them to tolerate not being sure.', 'Use it to help a group practice sitting with uncertainty.', array['Groups']::text[], '25 minutes', 'Cards pose mild tasks like leaving a sentence unfinished. Players report and rate discomfort. Debrief on what they noticed about the urge to fix.', '[{"id": "f0", "type": "textarea", "label": "The card I drew:"}, {"id": "f1", "type": "textarea", "label": "My discomfort before and after:"}, {"id": "f2", "type": "textarea", "label": "What I did with the urge to fix it:"}, {"id": "f3", "type": "textarea", "label": "What I will try next:"}]'::jsonb, array['OCD', 'game', 'exposure']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('panic-sensations-map-page', 'Panic Sensations Map Page', 'worksheet'::resource_kind, 'A body outline for marking where sensations show up.', 'Use it to help a client observe panic sensations with curiosity.', array['Adults']::text[], '20 minutes', 'The client marks sensations on the outline and rates each. Normalize that the body can give strong signals. Pair with a breathing log.', '[{"id": "f0", "type": "textarea", "label": "Where I feel sensations:"}, {"id": "f1", "type": "textarea", "label": "How strong each is (0 to 10):"}, {"id": "f2", "type": "textarea", "label": "What I tell myself about them:"}, {"id": "f3", "type": "textarea", "label": "What helps them pass:"}]'::jsonb, array['panic attacks', 'self-monitoring', 'grounding']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('feared-prediction-versus-outcome-panic-log', 'Feared Prediction Versus Outcome Panic Log', 'cbt'::resource_kind, 'A log comparing what the client predicted in a surge with what happened.', 'Use it to help a client test catastrophic predictions.', array['Adults']::text[], 'One week', 'The client logs each surge, what they feared and how it ended. At review, look for patterns in outcomes.', '[{"id": "f0", "type": "textarea", "label": "The sensations and what I feared:"}, {"id": "f1", "type": "textarea", "label": "What I did:"}, {"id": "f2", "type": "textarea", "label": "What actually happened:"}, {"id": "f3", "type": "textarea", "label": "What I will tell myself next time:"}]'::jsonb, array['panic attacks', 'thinking traps', 'core CBT']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('surfing-sensations-practice-page', 'Surfing Sensations Practice Page', 'act'::resource_kind, 'A page for observing a surge of sensation without fighting it.', 'Use it to help a client let a surge rise and fall.', array['Adults']::text[], '15 minutes', 'Practice in session with mild sensations. The client describes the sensation as shape and size. Reinforce willingness.', '[{"id": "f0", "type": "textarea", "label": "Sensations I noticed:"}, {"id": "f1", "type": "textarea", "label": "How I described them:"}, {"id": "f2", "type": "textarea", "label": "What changed over a few minutes:"}, {"id": "f3", "type": "textarea", "label": "What I did instead of fighting:"}]'::jsonb, array['panic attacks', 'willingness', 'mindfulness']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('slow-breathing-and-cool-water-surge-plan', 'Slow Breathing and Cool Water Surge Plan', 'dbt'::resource_kind, 'A plan combining slow breathing and cool water on the face.', 'Use it to give a client a body-based way to come down.', array['Adults']::text[], '20 minutes', 'Check for any health reasons to avoid cold. Practice both in session. The client rates arousal before and after.', '[{"id": "f0", "type": "textarea", "label": "When I will use the plan:"}, {"id": "f1", "type": "textarea", "label": "Arousal before (0 to 10):"}, {"id": "f2", "type": "textarea", "label": "Arousal after (0 to 10):"}, {"id": "f3", "type": "textarea", "label": "The part that worked best:"}]'::jsonb, array['panic attacks', 'distress tolerance', 'core DBT']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('partner-role-during-a-panic-surge', 'Partner Role During a Panic Surge', 'couples'::resource_kind, 'Partners agree on how the other will help during a surge.', 'Use it to help a partner stay calm and supportive.', array['Couples']::text[], '30 minutes', 'The one who has surges lists what helps. The partner learns three steps: stay calm, speak slowly, stay near. Practice once in session.', '[{"id": "f0", "type": "textarea", "label": "Partner A: What helps me during a surge:"}, {"id": "f1", "type": "textarea", "label": "Partner A: What does not help:"}, {"id": "f2", "type": "textarea", "label": "Partner B: The steps I will follow:"}, {"id": "f3", "type": "textarea", "label": "Both: How we will debrief later:"}]'::jsonb, array['panic attacks', 'support', 'couples']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('family-rules-poster-co-create', 'Family Rules Poster Co-Create', 'kids'::resource_kind, 'Children and parents decorate a short poster of shared family rules.', 'Use it to help a family agree on a few clear rules together.', array['Children']::text[], '40 minutes', 'Limit rules to four positively stated ones. The child draws pictures and the parent adds a line about what happens when rules are met. Post it where all can see.', '[{"id": "f0", "type": "textarea", "label": "Our four rules:"}, {"id": "f1", "type": "textarea", "label": "Why each matters to me:"}, {"id": "f2", "type": "textarea", "label": "What happens when we follow them:"}, {"id": "f3", "type": "textarea", "label": "Where we will hang the poster:"}]'::jsonb, array['parenting', 'children', 'routines']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('praise-practice-card-game', 'Praise Practice Card Game', 'game'::resource_kind, 'Parents draw cards and practice specific, labeled praise.', 'Use it to help parents get comfortable giving specific praise.', array['Groups']::text[], '25 minutes', 'Cards describe child behaviors. Parents say a specific praise aloud. Debrief on how it felt to give and receive.', '[{"id": "f0", "type": "textarea", "label": "A praise I gave:"}, {"id": "f1", "type": "textarea", "label": "How it felt:"}, {"id": "f2", "type": "textarea", "label": "A moment this week to use it:"}, {"id": "f3", "type": "textarea", "label": "What I noticed in others:"}]'::jsonb, array['parenting', 'game', 'communication']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('routines-rhythm-chart-for-parents', 'Routines Rhythm Chart for Parents', 'worksheet'::resource_kind, 'A chart for mapping a predictable daily rhythm.', 'Use it to help parents build predictable days.', array['Adults']::text[], '30 minutes', 'Map morning, after school and bedtime. Keep a few anchor points. Adjust after a week. Review the page together at the next visit and adjust it to fit this client.', '[{"id": "f0", "type": "textarea", "label": "Our morning rhythm:"}, {"id": "f1", "type": "textarea", "label": "Our after-school rhythm:"}, {"id": "f2", "type": "textarea", "label": "Our bedtime rhythm:"}, {"id": "f3", "type": "textarea", "label": "One anchor I will keep:"}]'::jsonb, array['parenting', 'routines', 'planning']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('parent-harsh-thought-reset-page', 'Parent Harsh Thought Reset Page', 'cbt'::resource_kind, 'A page for catching harsh thoughts about oneself or the child.', 'Use it to help a parent respond from calm.', array['Adults']::text[], '25 minutes', 'Identify the thought when a parent loses patience. Offer a more balanced one. Include self-compassion.', '[{"id": "f0", "type": "textarea", "label": "A hard parenting moment:"}, {"id": "f1", "type": "textarea", "label": "The thought I had:"}, {"id": "f2", "type": "textarea", "label": "A balanced thought:"}, {"id": "f3", "type": "textarea", "label": "How I want to respond next time:"}]'::jsonb, array['parenting', 'thinking traps', 'core CBT']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('parent-values-compass-for-tired-days', 'Parent Values Compass for Tired Days', 'act'::resource_kind, 'A page connecting parenting actions to values.', 'Use it to help a parent act on what matters even when tired.', array['Adults']::text[], '25 minutes', 'Ask what kind of parent they want to be. Name small actions that fit. Acknowledge limits. Review the page together at the next visit and adjust it to fit this client.', '[{"id": "f0", "type": "textarea", "label": "The parent I want to be:"}, {"id": "f1", "type": "textarea", "label": "Actions that fit this:"}, {"id": "f2", "type": "textarea", "label": "What gets in the way:"}, {"id": "f3", "type": "textarea", "label": "One action this week:"}]'::jsonb, array['parenting', 'values', 'committed action']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('self-care-minutes-plan-for-new-parents', 'Self-Care Minutes Plan for New Parents', 'dbt'::resource_kind, 'A plan for scheduling short restful moments.', 'Use it to help a new parent protect small pockets of rest.', array['Adults']::text[], '25 minutes', 'Be realistic about time. List five-minute options and who can cover. If the parent mentions harming themselves or the baby, review safety and name 988 (call or text).', '[{"id": "f0", "type": "textarea", "label": "Five-minute options for me:"}, {"id": "f1", "type": "textarea", "label": "Who can help me:"}, {"id": "f2", "type": "textarea", "label": "When I will try one:"}, {"id": "f3", "type": "textarea", "label": "If I feel unsafe, 988 (call or text) and my support person:"}]'::jsonb, array['perinatal and postpartum', 'emotion regulation', 'support']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('night-shifts-and-support-agreement', 'Night Shifts and Support Agreement', 'couples'::resource_kind, 'Partners divide night duties and plan rest.', 'Use it to help partners share the load fairly.', array['Couples']::text[], '35 minutes', 'List night tasks and divide them. Agree on how to ask for relief. Review weekly. Review the page together at the next visit and adjust it to fit this client.', '[{"id": "f0", "type": "textarea", "label": "Partner A: What I can cover:"}, {"id": "f1", "type": "textarea", "label": "Partner B: What I can cover:"}, {"id": "f2", "type": "textarea", "label": "Both: How to ask for relief:"}, {"id": "f3", "type": "textarea", "label": "Both: When we will review:"}]'::jsonb, array['perinatal and postpartum', 'planning', 'couples']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('big-sibling-feelings-booklet', 'Big Sibling Feelings Booklet', 'kids'::resource_kind, 'Older children draw a book about being a big sibling.', 'Use it to help an older child express feelings about a new baby.', array['Children']::text[], '35 minutes', 'Provide paper and crayons. The child draws what they like and find hard. The parent sets aside special time with them.', '[{"id": "f0", "type": "textarea", "label": "What I like about the baby:"}, {"id": "f1", "type": "textarea", "label": "What is hard:"}, {"id": "f2", "type": "textarea", "label": "What I want to do with my grown-up:"}, {"id": "f3", "type": "textarea", "label": "My special job:"}]'::jsonb, array['perinatal and postpartum', 'children', 'connection']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('new-parent-worry-swap', 'New Parent Worry Swap', 'game'::resource_kind, 'Players trade worries on cards and offer one kind reply.', 'Use it to help a group of new parents feel less alone.', array['Groups']::text[], '30 minutes', 'Players write worries anonymously and draw one to answer. Debrief on how common worries are. Review the page together at the next visit and adjust it to fit this client.', '[{"id": "f0", "type": "textarea", "label": "A worry I wrote:"}, {"id": "f1", "type": "textarea", "label": "A reply I gave:"}, {"id": "f2", "type": "textarea", "label": "A reply I received:"}, {"id": "f3", "type": "textarea", "label": "What I take with me:"}]'::jsonb, array['perinatal and postpartum', 'game', 'support']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('sleep-and-mood-notes-for-new-parents', 'Sleep and Mood Notes for New Parents', 'worksheet'::resource_kind, 'A log of sleep and mood without goals.', 'Use it to help a parent notice patterns and ask for help.', array['Adults']::text[], 'One week', 'Record hours slept and mood. Do not set targets. Look for the toughest times and plan support. Review the page together at the next visit and adjust it to fit this client.', '[{"id": "f0", "type": "textarea", "label": "Hours I slept:"}, {"id": "f1", "type": "textarea", "label": "My mood today (0 to 10):"}, {"id": "f2", "type": "textarea", "label": "The hardest time of day:"}, {"id": "f3", "type": "textarea", "label": "Help I could ask for:"}]'::jsonb, array['perinatal and postpartum', 'self-monitoring', 'support']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('inner-critic-response-page', 'Inner Critic Response Page', 'cbt'::resource_kind, 'A page for answering the inner critic with a fair reply.', 'Use it to help a client respond to self-criticism.', array['Adults']::text[], '25 minutes', 'Write the critic''s lines. Then write what a fair friend would say. Practice aloud. Review the page together at the next visit and adjust it to fit this client.', '[{"id": "f0", "type": "textarea", "label": "The critic says:"}, {"id": "f1", "type": "textarea", "label": "What a fair friend would say:"}, {"id": "f2", "type": "textarea", "label": "A balanced reply:"}, {"id": "f3", "type": "textarea", "label": "Where I will use it:"}]'::jsonb, array['self-esteem', 'self-talk', 'core CBT']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('self-compassion-break-page', 'Self-Compassion Break Page', 'act'::resource_kind, 'A page for a brief pause with kindness in hard moments.', 'Use it to help a client meet struggle with warmth.', array['Adults']::text[], '15 minutes', 'Teach the three parts: notice pain, common humanity, kindness. Practice together. Review the page together at the next visit and adjust it to fit this client.', '[{"id": "f0", "type": "textarea", "label": "A hard moment:"}, {"id": "f1", "type": "textarea", "label": "What others also feel:"}, {"id": "f2", "type": "textarea", "label": "A kind phrase for myself:"}, {"id": "f3", "type": "textarea", "label": "How it felt:"}]'::jsonb, array['self-esteem', 'self-compassion', 'mindfulness']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('building-mastery-skill-page', 'Building Mastery Skill Page', 'dbt'::resource_kind, 'A page for planning one doable thing to build competence.', 'Use it to help a client collect small proofs of capability.', array['Adults']::text[], '20 minutes', 'Choose something small. Plan, do and record. Note how it felt. Review the page together at the next visit and adjust it to fit this client.', '[{"id": "f0", "type": "textarea", "label": "What I will do:"}, {"id": "f1", "type": "textarea", "label": "When:"}, {"id": "f2", "type": "textarea", "label": "How I felt after:"}, {"id": "f3", "type": "textarea", "label": "What it shows me about myself:"}]'::jsonb, array['self-esteem', 'skills', 'core DBT']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('strengths-letters-exchange', 'Strengths Letters Exchange', 'couples'::resource_kind, 'Partners write letters naming each other''s strengths.', 'Use it to help partners hear what they are valued for.', array['Couples']::text[], '30 minutes', 'Each partner writes a short letter naming strengths with examples. They read aloud or exchange. Review the page together at the next visit and adjust it to fit this client.', '[{"id": "f0", "type": "textarea", "label": "Partner A: Strengths I see in my partner:"}, {"id": "f1", "type": "textarea", "label": "Partner B: Strengths I see in my partner:"}, {"id": "f2", "type": "textarea", "label": "Both: Which one meant the most:"}, {"id": "f3", "type": "textarea", "label": "Both: How to remind each other:"}]'::jsonb, array['self-esteem', 'strengths', 'couples']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('four-part-strengths-shield-drawing', 'Four-Part Strengths Shield Drawing', 'kids'::resource_kind, 'Children draw a shield with pictures of things they are good at.', 'Use it to help a child see their strengths.', array['Children']::text[], '35 minutes', 'Divide a shield into four. The child draws things they do well, like and are proud of. The parent adds a compliment.', '[{"id": "f0", "type": "textarea", "label": "Things I am good at:"}, {"id": "f1", "type": "textarea", "label": "Things I love:"}, {"id": "f2", "type": "textarea", "label": "Something I am proud of:"}, {"id": "f3", "type": "textarea", "label": "What my grown-up added:"}]'::jsonb, array['self-esteem', 'children', 'strengths']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('conversation-opener-practice-cards', 'Conversation Opener Practice Cards', 'game'::resource_kind, 'Players practice opening lines with cards.', 'Use it to help a group rehearse low-stakes conversation.', array['Groups']::text[], '25 minutes', 'Cards hold prompts like a weekend question. Players pair up and practice. Debrief on what felt easier.', '[{"id": "f0", "type": "textarea", "label": "A prompt I tried:"}, {"id": "f1", "type": "textarea", "label": "How it went:"}, {"id": "f2", "type": "textarea", "label": "What I noticed in my body:"}, {"id": "f3", "type": "textarea", "label": "Where I will use one:"}]'::jsonb, array['social anxiety', 'game', 'exposure']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('social-fear-ladder-page', 'Social Fear Ladder Page', 'worksheet'::resource_kind, 'A ladder of social situations from easiest to hardest.', 'Use it to help a client plan graded steps.', array['Adults']::text[], '30 minutes', 'List ten situations and rate each. Choose the first step. Plan how to review. Review the page together at the next visit and adjust it to fit this client.', '[{"id": "f0", "type": "textarea", "label": "Situations from easiest to hardest:"}, {"id": "f1", "type": "textarea", "label": "My first step:"}, {"id": "f2", "type": "textarea", "label": "When I will try it:"}, {"id": "f3", "type": "textarea", "label": "What I will record:"}]'::jsonb, array['social anxiety', 'exposure', 'planning']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('spotlight-noticing-prediction-test', 'Spotlight Noticing Prediction Test', 'cbt'::resource_kind, 'An experiment testing how much others notice.', 'Use it to help a client check their sense of being watched.', array['Adults']::text[], '25 minutes', 'Predict how much others notice. Test it in a small way. Compare. Review the page together at the next visit and adjust it to fit this client.', '[{"id": "f0", "type": "textarea", "label": "My prediction:"}, {"id": "f1", "type": "textarea", "label": "The test:"}, {"id": "f2", "type": "textarea", "label": "What I observed:"}, {"id": "f3", "type": "textarea", "label": "What I take from it:"}]'::jsonb, array['social anxiety', 'behavioral experiment', 'thinking traps']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('attention-outward-social-practice-log', 'Attention Outward Social Practice Log', 'act'::resource_kind, 'A page for turning attention from self to surroundings.', 'Use it to help a client shift focus in social moments.', array['Adults']::text[], '20 minutes', 'Practice noticing sounds and details in session. Try in a low-stakes setting. Review the page together at the next visit and adjust it to fit this client.', '[{"id": "f0", "type": "textarea", "label": "Where I practiced:"}, {"id": "f1", "type": "textarea", "label": "What I noticed around me:"}, {"id": "f2", "type": "textarea", "label": "How my self-focus changed:"}, {"id": "f3", "type": "textarea", "label": "Where I will try next:"}]'::jsonb, array['social anxiety', 'mindfulness', 'values']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('interpersonal-confidence-rehearsal-page', 'Interpersonal Confidence Rehearsal Page', 'dbt'::resource_kind, 'A page for rehearsing a conversation with skills.', 'Use it to help a client prepare a real interaction.', array['Adults']::text[], '30 minutes', 'Choose an upcoming interaction. Role-play with it. Plan for nerves. Review the page together at the next visit and adjust it to fit this client.', '[{"id": "f0", "type": "textarea", "label": "The interaction:"}, {"id": "f1", "type": "textarea", "label": "What I want to say:"}, {"id": "f2", "type": "textarea", "label": "How I will handle nerves:"}, {"id": "f3", "type": "textarea", "label": "How it went:"}]'::jsonb, array['social anxiety', 'interpersonal effectiveness', 'communication']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('two-ways-of-grieving-partner-conversation', 'Two Ways of Grieving Partner Conversation', 'couples'::resource_kind, 'Partners share how each grieves and what they need.', 'Use it to help partners respect different ways of grieving.', array['Couples']::text[], '40 minutes', 'Each partner describes their way. Invite curiosity not judgment. Plan one shared ritual. Review the page together at the next visit and adjust it to fit this client.', '[{"id": "f0", "type": "textarea", "label": "Partner A: How I grieve:"}, {"id": "f1", "type": "textarea", "label": "Partner B: How I grieve:"}, {"id": "f2", "type": "textarea", "label": "Both: What we need from each other:"}, {"id": "f3", "type": "textarea", "label": "Both: A shared ritual:"}]'::jsonb, array['grief and loss', 'support', 'couples']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('memory-keepsake-box-decorating', 'Memory Keepsake Box Decorating', 'kids'::resource_kind, 'Children decorate a box and fill it with memories.', 'Use it to help a child hold memories of someone they lost.', array['Children']::text[], '40 minutes', 'Decorate a box. The child adds drawings and objects. The parent listens to stories. Follow the child''s pace.', '[{"id": "f0", "type": "textarea", "label": "Who my box is for:"}, {"id": "f1", "type": "textarea", "label": "What I put inside:"}, {"id": "f2", "type": "textarea", "label": "A favorite memory:"}, {"id": "f3", "type": "textarea", "label": "Where we will keep it:"}]'::jsonb, array['grief and loss', 'children', 'art']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('remembering-circle-game', 'Remembering Circle Game', 'game'::resource_kind, 'Players share a memory on a prompt card.', 'Use it to help a group honor a loss together.', array['Groups']::text[], '30 minutes', 'Cards prompt memories like a favorite sound. Players choose to share or pass. Debrief gently. Review the page together at the next visit and adjust it to fit this client.', '[{"id": "f0", "type": "textarea", "label": "The prompt I drew:"}, {"id": "f1", "type": "textarea", "label": "What I shared:"}, {"id": "f2", "type": "textarea", "label": "How it felt:"}, {"id": "f3", "type": "textarea", "label": "What helped:"}]'::jsonb, array['grief and loss', 'game', 'connection']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('grief-wave-timing-and-soothing-log', 'Grief Wave Timing and Soothing Log', 'worksheet'::resource_kind, 'A tracker of waves of grief and what helped.', 'Use it to help a client see grief come and go.', array['Adults']::text[], 'One week', 'Log waves with times and triggers. Note what soothed. No goals. Review the page together at the next visit and adjust it to fit this client.', '[{"id": "f0", "type": "textarea", "label": "When the wave came:"}, {"id": "f1", "type": "textarea", "label": "What triggered it:"}, {"id": "f2", "type": "textarea", "label": "What helped:"}, {"id": "f3", "type": "textarea", "label": "What I need next:"}]'::jsonb, array['grief and loss', 'self-monitoring', 'support']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('guilt-and-should-thoughts-page', 'Guilt and Should Thoughts Page', 'cbt'::resource_kind, 'A page for looking at guilt thoughts after a loss.', 'Use it to help a client look at should thoughts kindly.', array['Adults']::text[], '25 minutes', 'List should thoughts and what the client knew then. Write a fair reply. Review the page together at the next visit and adjust it to fit this client.', '[{"id": "f0", "type": "textarea", "label": "A should thought:"}, {"id": "f1", "type": "textarea", "label": "What I knew at the time:"}, {"id": "f2", "type": "textarea", "label": "A fairer reply:"}, {"id": "f3", "type": "textarea", "label": "What I want to say to myself:"}]'::jsonb, array['grief and loss', 'thinking traps', 'core CBT']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('values-in-relationships-page', 'Values in Relationships Page', 'act'::resource_kind, 'A page clarifying how the client wants to show up.', 'Use it to help a client act on values in a relationship.', array['Adults']::text[], '25 minutes', 'Ask how they want to be with a person. Name actions. Notice barriers. Review the page together at the next visit and adjust it to fit this client.', '[{"id": "f0", "type": "textarea", "label": "The relationship:"}, {"id": "f1", "type": "textarea", "label": "How I want to show up:"}, {"id": "f2", "type": "textarea", "label": "One action:"}, {"id": "f3", "type": "textarea", "label": "What may get in the way:"}]'::jsonb, array['relationship issues', 'values', 'connection']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('give-skills-role-play-page', 'GIVE Skills Role-Play Page', 'dbt'::resource_kind, 'A page for practicing being gentle, interested, validating and easy.', 'Use it to help a client keep the relationship in mind during a request.', array['Adults']::text[], '25 minutes', 'Practice each letter in role-play. Choose one for the week. Review the page together at the next visit and adjust it to fit this client.', '[{"id": "f0", "type": "textarea", "label": "A conversation coming up:"}, {"id": "f1", "type": "textarea", "label": "How I will be gentle:"}, {"id": "f2", "type": "textarea", "label": "How I will validate:"}, {"id": "f3", "type": "textarea", "label": "How it went:"}]'::jsonb, array['relationship issues', 'interpersonal effectiveness', 'communication']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('soft-start-up-practice-sheet', 'Soft Start-Up Practice Sheet', 'couples'::resource_kind, 'Partners rewrite harsh openings into soft ones.', 'Use it to help partners raise concerns without blame.', array['Couples']::text[], '30 minutes', 'Each writes a harsh opener and rewrites it. Practice aloud. Review the page together at the next visit and adjust it to fit this client.', '[{"id": "f0", "type": "textarea", "label": "Partner A: Harsh opener and soft rewrite:"}, {"id": "f1", "type": "textarea", "label": "Partner B: Harsh opener and soft rewrite:"}, {"id": "f2", "type": "textarea", "label": "Both: What changed:"}, {"id": "f3", "type": "textarea", "label": "Both: Where we will use it:"}]'::jsonb, array['relationship issues', 'Gottman', 'communication']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('family-feelings-tree', 'Family Feelings Tree', 'kids'::resource_kind, 'Children and family draw a tree of feelings and who they share with.', 'Use it to help family members talk about feelings.', array['Children']::text[], '35 minutes', 'Draw a tree and add leaves for feelings. The parent adds their own. Talk about who listens. Review the page together at the next visit and adjust it to fit this client.', '[{"id": "f0", "type": "textarea", "label": "Feelings on my leaves:"}, {"id": "f1", "type": "textarea", "label": "Who I tell:"}, {"id": "f2", "type": "textarea", "label": "What helps me share:"}, {"id": "f3", "type": "textarea", "label": "What my grown-up added:"}]'::jsonb, array['relationship issues', 'children', 'family']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('listening-telephone-game', 'Listening Telephone Game', 'game'::resource_kind, 'Players pass a message and practice listening.', 'Use it to help a group notice how listening shapes understanding.', array['Groups']::text[], '20 minutes', 'Pass a short message and compare. Then practice reflecting. Debrief on listening habits. Review the page together at the next visit and adjust it to fit this client.', '[{"id": "f0", "type": "textarea", "label": "What changed in the message:"}, {"id": "f1", "type": "textarea", "label": "What helped me listen:"}, {"id": "f2", "type": "textarea", "label": "What got in the way:"}, {"id": "f3", "type": "textarea", "label": "Where I will practice:"}]'::jsonb, array['relationship issues', 'game', 'communication']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('safety-and-support-circle-page', 'Safety and Support Circle Page', 'worksheet'::resource_kind, 'A page naming safe people and what each can help with.', 'Use it to help a client map support without recounting events.', array['Adults']::text[], '25 minutes', 'Keep to present supports. The client names people and places that feel safe. Never ask for details of what happened. Note reporting duties as relevant.', '[{"id": "f0", "type": "textarea", "label": "People who feel safe:"}, {"id": "f1", "type": "textarea", "label": "What each can help with:"}, {"id": "f2", "type": "textarea", "label": "Places where I feel safe:"}, {"id": "f3", "type": "textarea", "label": "Someone I will reach out to this week:"}]'::jsonb, array['sexual abuse', 'safety', 'support']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('present-moment-anchor-card', 'Present Moment Anchor Card', 'cbt'::resource_kind, 'A card with grounding steps for present-focused calm.', 'Use it to help a client come back to the present.', array['Adults']::text[], '20 minutes', 'Teach steps in session and practice. Do not link to past events. Review the page together at the next visit and adjust it to fit this client.', '[{"id": "f0", "type": "textarea", "label": "What I see, hear and feel now:"}, {"id": "f1", "type": "textarea", "label": "A phrase to remind me I am here:"}, {"id": "f2", "type": "textarea", "label": "How steady I feel (0 to 10):"}, {"id": "f3", "type": "textarea", "label": "Where I will keep the card:"}]'::jsonb, array['sexual abuse', 'grounding', 'core CBT']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('values-and-pacing-page', 'Values and Pacing Page', 'act'::resource_kind, 'A page for choosing values-based actions at a safe pace.', 'Use it to help a client move toward what matters at their pace.', array['Adults']::text[], '25 minutes', 'The client chooses the pace. Focus on today''s actions, not on past events. Review the page together at the next visit and adjust it to fit this client.', '[{"id": "f0", "type": "textarea", "label": "Something that matters to me:"}, {"id": "f1", "type": "textarea", "label": "A small step:"}, {"id": "f2", "type": "textarea", "label": "How I will pace myself:"}, {"id": "f3", "type": "textarea", "label": "Who can support me:"}]'::jsonb, array['sexual abuse', 'values', 'pacing']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('distress-tolerance-menu-for-overwhelm', 'Distress Tolerance Menu for Overwhelm', 'dbt'::resource_kind, 'A menu of skills for waves of overwhelm.', 'Use it to give a client choices when overwhelmed.', array['Adults']::text[], '25 minutes', 'Build a menu of grounding and soothing skills. Practice one. If the client mentions self-harm, review safety and name 988 (call or text).', '[{"id": "f0", "type": "textarea", "label": "Skills I can use:"}, {"id": "f1", "type": "textarea", "label": "The one I will try first:"}, {"id": "f2", "type": "textarea", "label": "Who I can reach:"}, {"id": "f3", "type": "textarea", "label": "988 (call or text) if I feel unsafe:"}]'::jsonb, array['sexual abuse', 'distress tolerance', 'grounding']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('partner-safety-and-pacing-agreement', 'Partner Safety and Pacing Agreement', 'couples'::resource_kind, 'Partners agree on pacing in closeness and talk.', 'Use it to help partners respect each other''s limits.', array['Couples']::text[], '35 minutes', 'The affected partner states what feels safe. The partner agrees to follow. A stop word is chosen. No details of past events are required.', '[{"id": "f0", "type": "textarea", "label": "Partner A: What helps me feel safe:"}, {"id": "f1", "type": "textarea", "label": "Partner B: How I will respect that:"}, {"id": "f2", "type": "textarea", "label": "Both: Our stop word:"}, {"id": "f3", "type": "textarea", "label": "Both: How we will check in:"}]'::jsonb, array['sexual abuse', 'safety', 'couples']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('my-coping-menu-placemat', 'My Coping Menu Placemat', 'kids'::resource_kind, 'Children decorate a placemat of coping choices.', 'Use it to help a child choose from a list when upset.', array['Children']::text[], '35 minutes', 'Provide paper and colors. The child draws five coping choices. The parent laminates or posts it. Review the page together at the next visit and adjust it to fit this client.', '[{"id": "f0", "type": "textarea", "label": "Five things that help me:"}, {"id": "f1", "type": "textarea", "label": "The one I like best:"}, {"id": "f2", "type": "textarea", "label": "Where I will keep it:"}, {"id": "f3", "type": "textarea", "label": "How my grown-up can remind me:"}]'::jsonb, array['coping skills', 'children', 'regulation']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('coping-skill-sketch-and-guess-round', 'Coping Skill Sketch and Guess Round', 'game'::resource_kind, 'Players draw coping skills while others guess.', 'Use it to help a group review a range of coping skills.', array['Groups']::text[], '25 minutes', 'Use skill cards. Debrief on which skills to try this week. Review the page together at the next visit and adjust it to fit this client.', '[{"id": "f0", "type": "textarea", "label": "Skills I drew:"}, {"id": "f1", "type": "textarea", "label": "Skills I learned:"}, {"id": "f2", "type": "textarea", "label": "One I will try:"}, {"id": "f3", "type": "textarea", "label": "When:"}]'::jsonb, array['coping skills', 'game', 'skills']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('coping-skills-test-drive-log', 'Coping Skills Test Drive Log', 'worksheet'::resource_kind, 'A log of trying a skill and rating its helpfulness.', 'Use it to help a client find which skills fit them.', array['Adults']::text[], 'One week', 'Try a skill per day. Rate before and after. Review what helped. Review the page together at the next visit and adjust it to fit this client.', '[{"id": "f0", "type": "textarea", "label": "Skill I tried:"}, {"id": "f1", "type": "textarea", "label": "Rating before and after:"}, {"id": "f2", "type": "textarea", "label": "What helped:"}, {"id": "f3", "type": "textarea", "label": "What I will keep:"}]'::jsonb, array['coping skills', 'self-monitoring', 'toolbox']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('coping-thoughts-rehearsal-page', 'Coping Thoughts Rehearsal Page', 'cbt'::resource_kind, 'A page of coping statements rehearsed ahead of time.', 'Use it to help a client have thoughts ready for hard moments.', array['Adults']::text[], '20 minutes', 'Write three statements that feel true. Practice aloud and place them where they are seen. Review the page together at the next visit and adjust it to fit this client.', '[{"id": "f0", "type": "textarea", "label": "A hard moment coming up:"}, {"id": "f1", "type": "textarea", "label": "My three statements:"}, {"id": "f2", "type": "textarea", "label": "Where I will keep them:"}, {"id": "f3", "type": "textarea", "label": "How I will practice:"}]'::jsonb, array['coping skills', 'self-talk', 'core CBT']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('choice-point-page', 'Choice Point Page', 'act'::resource_kind, 'A page mapping toward and away moves at a choice point.', 'Use it to help a client notice choices under pressure.', array['Adults']::text[], '25 minutes', 'Draw the choice point. List hooks, away moves and toward moves. Review the page together at the next visit and adjust it to fit this client.', '[{"id": "f0", "type": "textarea", "label": "A recent hard moment:"}, {"id": "f1", "type": "textarea", "label": "What hooked me:"}, {"id": "f2", "type": "textarea", "label": "An away move and a toward move:"}, {"id": "f3", "type": "textarea", "label": "What I will try:"}]'::jsonb, array['coping skills', 'values', 'committed action']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('riding-the-wave-of-fear-page', 'Riding the Wave of Fear Page', 'dbt'::resource_kind, 'A page for watching fear rise and fall during a planned step.', 'Use it to help a client stay with a planned step while fear changes.', array['Adults']::text[], '25 minutes', 'Plan a small step. The client rates fear at intervals. Compare the curve. Review the page together at the next visit and adjust it to fit this client.', '[{"id": "f0", "type": "textarea", "label": "The step:"}, {"id": "f1", "type": "textarea", "label": "Fear ratings over time:"}, {"id": "f2", "type": "textarea", "label": "What I noticed:"}, {"id": "f3", "type": "textarea", "label": "What I will repeat:"}]'::jsonb, array['phobias', 'exposure', 'distress tolerance']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('partner-coach-for-facing-a-fear', 'Partner Coach for Facing a Fear', 'couples'::resource_kind, 'Partners learn how to coach without pushing.', 'Use it to help a partner encourage steps at the client''s pace.', array['Couples']::text[], '30 minutes', 'The one facing the fear sets the step. The partner learns to cheer, not rush. Plan a debrief. Review the page together at the next visit and adjust it to fit this client.', '[{"id": "f0", "type": "textarea", "label": "Partner A: My next step:"}, {"id": "f1", "type": "textarea", "label": "Partner B: How I will cheer:"}, {"id": "f2", "type": "textarea", "label": "Both: What not to do:"}, {"id": "f3", "type": "textarea", "label": "Both: Our debrief plan:"}]'::jsonb, array['phobias', 'support', 'couples']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('silly-fear-monster-redraw', 'Silly Fear Monster Redraw', 'kids'::resource_kind, 'Children draw their fear as a silly monster.', 'Use it to help a child make fear feel smaller.', array['Children']::text[], '30 minutes', 'The child draws the fear and then adds silly details. The parent keeps a light tone and praises bravery.', '[{"id": "f0", "type": "textarea", "label": "What my fear looks like:"}, {"id": "f1", "type": "textarea", "label": "The silly changes I made:"}, {"id": "f2", "type": "textarea", "label": "What I can do when it shows up:"}, {"id": "f3", "type": "textarea", "label": "What my grown-up said:"}]'::jsonb, array['phobias', 'children', 'art']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('fear-ladder-climb-board', 'Fear Ladder Climb Board', 'game'::resource_kind, 'Players move up a ladder by naming and trying steps.', 'Use it to help a group practice stepwise approach.', array['Groups']::text[], '30 minutes', 'Each player draws a ladder. They name steps and move up as they commit. Debrief on pacing. Review the page together at the next visit and adjust it to fit this client.', '[{"id": "f0", "type": "textarea", "label": "My ladder steps:"}, {"id": "f1", "type": "textarea", "label": "The step I committed to:"}, {"id": "f2", "type": "textarea", "label": "What helped:"}, {"id": "f3", "type": "textarea", "label": "What I learned:"}]'::jsonb, array['phobias', 'game', 'exposure']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('fear-facts-and-plan-page', 'Fear Facts and Plan Page', 'worksheet'::resource_kind, 'A page to list facts about a feared thing and a plan.', 'Use it to help a client prepare for contact with a feared thing.', array['Adults']::text[], '25 minutes', 'List what is known and what is guessed. Make a plan for contact. Review the page together at the next visit and adjust it to fit this client.', '[{"id": "f0", "type": "textarea", "label": "Facts I know:"}, {"id": "f1", "type": "textarea", "label": "Guesses I make:"}, {"id": "f2", "type": "textarea", "label": "My plan:"}, {"id": "f3", "type": "textarea", "label": "Who will support me:"}]'::jsonb, array['phobias', 'exposure', 'planning']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('appearance-comparison-thoughts-page', 'Appearance Comparison Thoughts Page', 'cbt'::resource_kind, 'A page for noticing comparison thoughts and replacing them.', 'Use it to help a client respond to comparison thoughts.', array['Adults']::text[], '25 minutes', 'Avoid any talk of measuring the body. Focus on thoughts and feelings. Review the page together at the next visit and adjust it to fit this client.', '[{"id": "f0", "type": "textarea", "label": "A time I compared myself:"}, {"id": "f1", "type": "textarea", "label": "The thought:"}, {"id": "f2", "type": "textarea", "label": "A fairer thought:"}, {"id": "f3", "type": "textarea", "label": "What I did instead:"}]'::jsonb, array['body image', 'thinking traps', 'self-compassion']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('body-kindness-actions-page', 'Body Kindness Actions Page', 'act'::resource_kind, 'A page of actions that honor the body without appearance goals.', 'Use it to help a client care for their body as a partner.', array['Adults']::text[], '20 minutes', 'List actions like rest or stretching. Keep focus on how the body helps. Review the page together at the next visit and adjust it to fit this client.', '[{"id": "f0", "type": "textarea", "label": "What my body helps me do:"}, {"id": "f1", "type": "textarea", "label": "Kind actions I can take:"}, {"id": "f2", "type": "textarea", "label": "How I will do one this week:"}, {"id": "f3", "type": "textarea", "label": "How it felt:"}]'::jsonb, array['body image', 'values', 'self-compassion']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('mirror-mindfulness-without-judgment-page', 'Mirror Mindfulness Without Judgment Page', 'dbt'::resource_kind, 'A page practicing neutral description when looking in a mirror.', 'Use it to help a client observe without judging.', array['Adults']::text[], '20 minutes', 'Practice neutral words in session. Avoid evaluating any part of the body. Review the page together at the next visit and adjust it to fit this client.', '[{"id": "f0", "type": "textarea", "label": "Neutral words I used:"}, {"id": "f1", "type": "textarea", "label": "Judgments that came up:"}, {"id": "f2", "type": "textarea", "label": "How I let them pass:"}, {"id": "f3", "type": "textarea", "label": "How I felt after:"}]'::jsonb, array['body image', 'mindfulness', 'core DBT']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('affirming-closeness-without-appearance-talk', 'Affirming Closeness Without Appearance Talk', 'couples'::resource_kind, 'Partners share ways to feel connected beyond looks.', 'Use it to help partners build closeness that is not about looks.', array['Couples']::text[], '30 minutes', 'Each partner names moments of closeness. Agree on kind phrases and avoid commentary on bodies. Review the page together at the next visit and adjust it to fit this client.', '[{"id": "f0", "type": "textarea", "label": "Partner A: Moments I feel close:"}, {"id": "f1", "type": "textarea", "label": "Partner B: Moments I feel close:"}, {"id": "f2", "type": "textarea", "label": "Both: Phrases we like:"}, {"id": "f3", "type": "textarea", "label": "Both: What we will try:"}]'::jsonb, array['body image', 'connection', 'couples']::text[], '2026-11-04T15:00:00+00:00'::timestamptz),
  ('super-body-helpers-collage', 'Super Body Helpers Collage', 'kids'::resource_kind, 'Children make a collage of things their body helps them do.', 'Use it to help a child value what their body does.', array['Children']::text[], '35 minutes', 'Provide magazines or drawings. The child glues activities. The parent adds one more. No comments on appearance.', '[{"id": "f0", "type": "textarea", "label": "Things my body helps me do:"}, {"id": "f1", "type": "textarea", "label": "My favorite:"}, {"id": "f2", "type": "textarea", "label": "What my grown-up added:"}, {"id": "f3", "type": "textarea", "label": "Where it will hang:"}]'::jsonb, array['body image', 'children', 'art']::text[], '2026-11-04T15:00:00+00:00'::timestamptz)
